import assert from 'node:assert/strict';
const root=process.argv[2];
const outcomes=[];
async function check(name,fn){try{await fn();outcomes.push({name,pass:true});}catch(e){if(e.code!=='ERR_ASSERTION')throw e;outcomes.push({name,pass:false,actual:e.actual,expected:e.expected});}}

const {OrdersDb}=await import(root+'/src/db.ts');const {refundOrder}=await import(root+'/src/factory.ts');await check('refund uses the injected module client',()=>{const db=new OrdersDb('synthetic://db');refundOrder(db);assert.equal(db.writes.length,1);});console.log(JSON.stringify(outcomes));process.exit(outcomes.every(x=>x.pass)?0:10);

