import assert from 'node:assert/strict';import {Database} from 'bun:sqlite';import {readdir} from 'node:fs/promises';
const db=new Database(':memory:');db.exec(await Bun.file('order-tags.sql').text());
try{const keys=db.query('pragma table_info(order_tag)').all().filter(c=>c.pk);assert.equal(keys.length,1);assert.equal(keys[0].name,'order_tag_id');db.exec("insert into order_tag(order_tag_id,order_id,tag_id) values ('first','order','tag')");assert.throws(()=>db.exec("insert into order_tag(order_tag_id,order_id,tag_id) values ('second','order','tag')"),/UNIQUE constraint failed/);const names=(await readdir('migrations')).sort();const ids=names.map(n=>n.split('_')[0]);assert.equal(new Set(ids).size,ids.length);console.log('Independent live SQLite key/uniqueness and migration registry passed');}catch(error){if(error.code!=='ERR_ASSERTION')throw error;console.log(error);process.exitCode=10;}finally{db.close();}

const migrationDb=new Database(':memory:');
try{
 const target='6b043c7591d240d6a866b6acf943b3eee0e523c6';
 const tree=Bun.spawnSync(['git','ls-tree','-r','--name-only',target,'--','migrations']);if(tree.exitCode!==0)throw new Error('target registry unavailable');
 const applied=new TextDecoder().decode(tree.stdout).trim().split('\n').filter(Boolean).sort();
 for(const file of applied){const value=Bun.spawnSync(['git','show',target+':'+file]);if(value.exitCode!==0)throw new Error('target migration unavailable');migrationDb.exec(new TextDecoder().decode(value.stdout));}
 const last=Math.max(...applied.map(file=>Number(file.split('/').pop().split('_')[0])));
 for(const file of (await readdir('migrations')).sort()){
  if(applied.includes('migrations/'+file))continue;
  assert.ok(Number(file.split('_')[0])>last,'new migration sorts before the applied target');
  migrationDb.exec(await Bun.file('migrations/'+file).text());
 }
 console.log('Existing target database accepts branch migrations in order');
}catch(error){if(error.code==='ERR_ASSERTION'||error.code?.startsWith('SQLITE_')){console.log(error);process.exitCode=10;}else throw error;}finally{migrationDb.close();}
